import json,math,statistics
from collections import Counter
import detector
rows=detector.load_jsonl(detector.TRAIN_PATH)
texts={lab:[r['text'] for r in rows if r['label']==lab] for lab in ('human','ai')}
cnt={lab:Counter() for lab in texts}
tot={lab:0 for lab in texts}
for lab in texts:
    for t in texts[lab]:
        for g in detector.char_ngrams(t,4):
            cnt[lab][g]+=1; tot[lab]+=1
V=len(set(cnt['human'])|set(cnt['ai']))
lo={}
for g in set(cnt['human'])|set(cnt['ai']):
    pa=(cnt['ai'][g]+0.5)/(tot['ai']+0.5*V)
    ph=(cnt['human'][g]+0.5)/(tot['human']+0.5*V)
    lo[g]=math.log(pa/ph)
top=sorted(lo,key=lambda g:-lo[g])[:40]
print('AI 偏向 4-gram:',[(g,round(lo[g],1),cnt['ai'][g],cnt['human'][g]) for g in top[:20]])
bot=sorted(lo,key=lambda g:lo[g])[:15]
print('人写偏向 4-gram:',[(g,round(lo[g],1)) for g in bot])

# 特征：文本中命中 top-K AI 偏向 4-gram 的密度，看两类分离度
K=60
ai_set=set(top[:K])
def rate(t):
    grams=detector.char_ngrams(t,4)
    if not grams: return 0
    return sum(1 for g in grams if g in ai_set)/len(grams)*100
for lab in texts:
    vals=[rate(t) for t in texts[lab]]
    print(lab,'ai4gram rate mean',round(statistics.mean(vals),2),'std',round(statistics.pstdev(vals),2))
